// === Tab: mySketch ===
let w;
let pg;

let leader;
let balls = [];
let N = 32;

let c0 = [46, 41, 78];
let c1 = [84, 19, 136];
let c2 = [217, 3, 104];
let c3 = [255, 212, 0];
let c4 = [241, 233, 218];

preload = () => {loadmyshader();}

function setup() {
	w = max(windowWidth, windowHeight);
	createCanvas(w, w, WEBGL);
	pg = createGraphics(w, w);
	pg.noStroke();

	leader = new Ball(null, 0, "#00000000");
	for(let i=0; i<N; i++){
		balls.push(new Ball(i==0?leader:balls[i-1], ((N-i)/N)*(w/4), color(255, pow((N-i)/N, 3)*255)));
	}
}

function draw() {
	pg.background(0);
	leader.v.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))); leader.v.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	for(let b=N-1; b>=0; b--){
		balls[b].move();
		balls[b].show();
	}

	shader(theShader);
	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("tex0", pg);
	theShader.setUniform("c0", c0);
	theShader.setUniform("c1", c1);
	theShader.setUniform("c2", c2);
	theShader.setUniform("c3", c3);
	theShader.setUniform("c4", c4);
	quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

class Ball{
	constructor(follow, size, color){
		this.v = createVector(w/2, w/2);
		this.f = follow;
		this.s = size;
		this.c = color;
	}

	move(){
		if(!this.f) return 0;
		let toward = p5.Vector.sub(this.f.v, this.v);
		if(toward.mag()<w/64) return 0;
		this.v.add(toward.mult(0.2));
	}

	show(){
		pg.fill(this.c);
		pg.circle(this.v.x, this.v.y, this.s);
	}
}

// === Tab: Shader ===
let theShader;
function loadmyshader(){
	theShader = createShader(vert, frag);
}

const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

const frag = `
#ifdef GL_ES
precision mediump float;
#endif

#define color_step 5.

uniform vec2 u_resolution;
uniform sampler2D tex0;
uniform vec3 c0;
uniform vec3 c1;
uniform vec3 c2;
uniform vec3 c3;
uniform vec3 c4;

vec2 last_px(in vec2 coord, in float ind){
    if(coord.x-ind<0.){
        return vec2(coord.x-ind+u_resolution.x, coord.y-1.);
    }
    else{
        return vec2(coord.x-1., coord.y);
    }
}

void main()
{
		vec2 fragCoord = gl_FragCoord.xy;
		fragCoord *= 0.5;
		fragCoord.y = u_resolution.y-fragCoord.y;

    fragCoord/=4.;
    fragCoord = floor(fragCoord);
    fragCoord*=4.;

    vec4 tex = texture2D(tex0, fragCoord/u_resolution);

    vec3 error_sum = vec3(0.);

    for(float i=1.; i<16.; i++){
        vec4 tex_prev = texture2D(tex0, last_px(fragCoord, i)/u_resolution);
        vec3 target_prev = floor( (tex_prev.rgb+error_sum*0.45)*color_step)/color_step;
        error_sum += tex_prev.rgb-target_prev;
    }
    vec3 target = vec3(0.);

		int c = int(floor( (tex.rgb+error_sum*0.45) *color_step));

		if(c==0){target = c0;}
		else if(c==1){target = c1;}
		else if(c==2){target = c2;}
		else if(c==3){target = c3;}
		else {target = c4;}

    tex.rgb = target/255.;

    gl_FragColor = tex;
}
`;

